<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderCertificateAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderCertificateAccessor trait.
 *
 * Covers null default, string/VO assignment via withCertificate,
 * getCertificate/certificate accessors, and isCertificateChanged with/without original.
 */
class TenantLoginProviderCertificateAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withCertificate creates a new instance with the Certificate set
     * from a string value, and getCertificate returns the primitive string.
     */
    public function testWithCertificateFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderCertificateAccessorUnitTest();

        // Act
        $result = $holder->withCertificate('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getCertificate());
    }
    /**
     * Asserts that withcertificate has access to the value object
     * from a string value, and getCertificate returns the primitive string.
     */
    public function testWithCertificateFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderCertificateAccessorUnitTest();

        // Act
        $result = $holder->withCertificate('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->certificate()->value());
    }
    public function testChangedCertificate(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderCertificateAccessorUnitTest();
        $original = $holder->withCertificate('one');
        $same = $holder->withCertificate('one');
        $modified = $holder->withCertificate('other');

        // Act
        $unchanged = $holder->isCertificateChanged();
        $withSame = $original->isCertificateChanged($same);
        $withDiferent = $original->isCertificateChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderCertificateAccessorUnitTest
{
    use TenantLoginProviderCertificateAccessor;
}
